qualified_questions.sparql_query:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX BO: <http://example.org/BO#>

SELECT ?operation (COUNT(?inputDataPoint) AS ?inputCount) (COUNT(?outputDataPoint) AS ?outputCount) (GROUP_CONCAT(DISTINCT STR(?inputType); separator=", ") AS ?inputTypes) (GROUP_CONCAT(DISTINCT STR(?outputType); separator=", ") AS ?outputTypes)
WHERE {
  ?operation rdf:type BO:Operation .
  OPTIONAL {
    ?operation BO:hasInputDataPoint ?inputDataPoint .
    ?inputDataPoint rdf:type ?inputType .
  }
  OPTIONAL {
    ?operation BO:hasOutputDataPoint ?outputDataPoint .
    ?outputDataPoint rdf:type ?outputType .
  }
}
GROUP BY ?operation

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX BO: <http://example.org/BO#>

SELECT ?device ?function ?command
WHERE {
  ?device rdf:type BO:Device ;
          BO:hasFunction ?function .
  ?function rdf:type BO:ControllingFunction ;
            BO:hasCommand ?command .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/BuildingOntology#>

SELECT ?device ?componentDevice ?service ?function
WHERE {
  ?device rdf:type BO:Device ;
          BO:consistsOf ?componentDevice .
  ?componentDevice BO:hasService ?service ;
                   BO:hasFunction ?function .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/BO#>

SELECT ?variable ?role
WHERE {
  ?variable rdf:type BO:Variable .
  OPTIONAL { 
    ?variable BO:describes ?aspect .
    BIND("Describes an aspect" AS ?role)
  }
  OPTIONAL { 
    ?inputDataPoint rdf:type BO:InputDataPoint ;
                    rdf:type BO:Variable .
    BIND("Serves as input data point for operations" AS ?role)
  }
  OPTIONAL { 
    ?outputDataPoint rdf:type BO:OutputDataPoint ;
                     rdf:type BO:Variable .
    BIND("Serves as output data point for operations" AS ?role)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/BuildingOntology#>

SELECT ?operationDescription
WHERE {
  BO:SET_OutputDataPoint rdfs:subClassOf BO:Operation .
  BO:SET_OutputDataPoint rdfs:label ?operationLabel .
  OPTIONAL { BO:SET_OutputDataPoint rdfs:comment ?operationDescription }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/BO#>

SELECT ?operation ?description
WHERE {
  ?operation a BO:GET_InputDataPoint .
  OPTIONAL { ?operation rdfs:comment ?description }
}

PREFIX BO: <http://example.org/BO#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?maxLength
WHERE {
  ?simpleTypeVariable a BO:SimpleTypeVariable ;
                      BO:hasDataRestriction_maxLength ?maxLength .
}

SELECT ?property
WHERE {
  ?property rdfs:domain BO:StructuredTypeVariable .
  FILTER NOT EXISTS {
    ?property rdfs:domain ?otherVariable .
    FILTER(?otherVariable != BO:StructuredTypeVariable)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/ontology/BO#>

SELECT ?areaNetwork
WHERE {
  ?areaNetwork rdf:type BO:AreaNetwork ;
               BO:netTechnologyCommunicationProtocol ?communicationProtocol ;
               BO:netTechnologyPhysicalStandard ?physicalStandard .
  FILTER(?communicationProtocol = "specific_communication_protocol" && ?physicalStandard = "particular_physical_standard")
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/ontology/BO#>

SELECT (COUNT(DISTINCT ?areaNetwork) AS ?count)
WHERE {
  ?areaNetwork rdf:type BO:AreaNetwork ;
               BO:oneM2MMethod ?oneM2MMethod ;
               BO:netTechnologyProfile ?netTechnologyProfile .
  FILTER(?oneM2MMethod = "certain_oneM2M_method" && ?netTechnologyProfile = "specific_net_technology_profile")
}

PREFIX BO: <http://example.org/ontology/BO#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?areaNetwork
WHERE {
  ?areaNetwork rdf:type BO:AreaNetwork ;
               BO:netTechnologyProfile ?technologyProfile ;
               BO:netTechnologyCommunicationProtocol ?communicationProtocol .
  FILTER(?technologyProfile = "specific_net_technology_profile" && ?communicationProtocol = "given_communication_protocol")
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/ontology/BO#>

SELECT ?areaNetwork ?physicalStandard
WHERE {
  ?areaNetwork rdf:type BO:AreaNetwork ;
               BO:netTechnologyCommunicationProtocol ?communicationProtocol ;
               BO:netTechnologyProfile ?technologyProfile ;
               BO:netTechnologyPhysicalStandard ?physicalStandard .
  FILTER(?communicationProtocol = "specific_communication_protocol" && ?technologyProfile = "certain_net_technology_profile")
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/BO#>

SELECT ?thing1 ?thing2
WHERE {
  ?thing1 a BO:Thing .
  ?thing2 a BO:Thing .
  FILTER(?thing1 != ?thing2)
  {
    SELECT ?thing (GROUP_CONCAT(DISTINCT ?property; separator=",") AS ?properties)
    WHERE {
      ?thing a BO:Thing ;
             BO:hasThingProperty ?property .
    }
    GROUP BY ?thing
  } 
  BIND(?thing1 AS ?thing) 
  BIND(?thing2 AS ?thing)
  FILTER(?thing1_properties = ?thing2_properties)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/BO#>

SELECT ?thing1 ?thing2
WHERE {
  ?thing1 rdf:type BO:Thing ;
          BO:hasThingProperty ?property1 ;
          BO:hasThingRelation ?thing2 .
  ?thing2 rdf:type BO:Thing ;
          BO:hasThingProperty ?property2 .
  FILTER(?property1 = ?property2)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/BO#>

SELECT (COUNT(DISTINCT ?property) AS ?uniqueProperties)
WHERE {
  { ?thing BO:hasThingProperty ?property . }
  UNION
  { ?thing BO:hasThingRelation ?property . }
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?versionIRI
WHERE {
  <https://git.onem2m.org/MAS/BaseOntology/raw/master/base_ontology.owl> owl:versionIRI ?versionIRI .
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?currentVersion ?previousVersion
WHERE {
  <https://git.onem2m.org/MAS/BaseOntology/raw/master/base_ontology.owl> rdf:type owl:Ontology ;
  owl:versionIRI ?currentVersion .
  FILTER(?currentVersion != <https://git.onem2m.org/MAS/BaseOntology/raw/3_6_0/base_ontology.owl>)
  <https://git.onem2m.org/MAS/BaseOntology/raw/3_6_0/base_ontology.owl> owl:versionIRI ?previousVersion .
}
